<?php

namespace Tests\Feature\Observability;

use Sentry\ClientInterface;
use Sentry\State\HubInterface;
use Tests\Feature\FeatureTest;

class SentryIntegrationTest extends FeatureTest
{
    public function test_sentry_hub_is_bound_in_container(): void
    {
        $this->assertTrue(
            $this->app->bound(HubInterface::class),
            'Sentry HubInterface is not bound — the service provider did not register.',
        );
    }

    public function test_sentry_client_has_dsn_when_configured(): void
    {
        config()->set('sentry.dsn', 'https://key@bugsink.example.com/1');

        // Re-resolve so the client picks up the DSN we just set.
        $hub = $this->app->make('sentry');
        $hub->bindClient(
            \Sentry\ClientBuilder::create(['dsn' => config('sentry.dsn')])->getClient()
        );

        $client = $hub->getClient();

        $this->assertInstanceOf(ClientInterface::class, $client);
        $this->assertNotNull(
            $client->getOptions()->getDsn(),
            'Sentry client has no DSN — exceptions would not be reported.',
        );
    }

    public function test_before_send_callback_is_configured(): void
    {
        $beforeSend = config('sentry.before_send');

        $this->assertNotNull(
            $beforeSend,
            'No before_send callback — TokenScrubber is mandatory per spec §15.1.',
        );
        $this->assertIsCallable($beforeSend);
    }

    public function test_traces_sample_rate_is_zero(): void
    {
        // Self-hosted collector constraint: never send performance traces.
        $this->assertSame(0.0, config('sentry.traces_sample_rate'));
    }

    public function test_send_default_pii_is_disabled(): void
    {
        $this->assertFalse(config('sentry.send_default_pii'));
    }

    public function test_logging_stack_includes_sentry_channel(): void
    {
        $stack = config('logging.channels.stack.channels');

        $this->assertContains(
            'sentry',
            $stack,
            'The default logging stack must include the sentry channel so Log::error() reaches Bugsink.',
        );
    }

    public function test_sentry_log_channel_exists(): void
    {
        $channel = config('logging.channels.sentry');

        $this->assertNotNull($channel, 'No sentry logging channel defined.');
        $this->assertSame('sentry', $channel['driver']);
    }
}
